from functools import lru_cache
import struct
@lru_cache(100)
def pack(ss):
    parts=[s.encode('utf-32-le') for s in ss]; offsets=[0]
    for p in parts: offsets.append(offsets[-1]+len(p))
    return bytearray(b''.join(parts)),struct.pack('<'+'i'*len(offsets),*offsets)
